.skills-track {
  animation: marquee 24s linear infinite;
}
@keyframes marquee {
  0%   { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

public class Item {
  private String name;
  private double price;

  public Item(String name, double price) {
    this.name  = name;
    this.price = price;
  }

  public void display() {
    System.out.println(name + " — $" + price);
  }
}
